  1	<?php
  2	/**
  3	 * Interactive developer menu for the Application Framework.
  4	 *
  5	 * Presents a numbered list of common developer tasks and dispatches
  6	 * to the appropriate Composer command or tool script via passthru().
  7	 * The menu loops until the developer selects option 0 (Exit).
  8	 *
  9	 * If the `vendor/` directory is absent when the script starts, a
 10	 * `composer install` is run automatically so the environment is always
 11	 * bootstrapped before further actions are attempted.
 12	 *
 13	 * Usage:
 14	 *   ./menu.sh        (Unix — see menu.sh wrapper)
 15	 *   menu.cmd         (Windows — see menu.cmd wrapper)
 16	 *   php tools/menu.php
 17	 *
 18	 * @package Application
 19	 * @subpackage Tools
 20	 */
 21	
 22	declare(strict_types=1);
 23	
 24	// ============================================================================
 25	// Pre-flight: ensure Composer dependencies are installed
 26	// ============================================================================
 27	
 28	/**
 29	 * Checks whether the `vendor/` directory exists relative to the project root.
 30	 * If it is missing, runs `composer install` automatically and aborts on failure.
 31	 *
 32	 * @return void
 33	 */
 34	function ensureVendorInstalled() : void
 35	{
 36	    $vendorDir = __DIR__ . '/../vendor';
 37	
 38	    if (is_dir($vendorDir))
 39	    {
 40	        return;
 41	    }
 42	
 43	    echo 'vendor/ directory not found. Running composer install...' . PHP_EOL;
 44	    passthru('composer install', $exitCode);
 45	
 46	    if ($exitCode !== 0)
 47	    {
 48	        echo 'composer install failed (exit code ' . $exitCode . '). Aborting.' . PHP_EOL;
 49	        exit(1);
 50	    }
 51	
 52	    echo PHP_EOL;
 53	}
 54	
 55	ensureVendorInstalled();
 56	
 57	// ============================================================================
 58	// Bootstrap — shared CLI utilities (writeln, color, prompt)
 59	// ============================================================================
 60	
 61	require_once __DIR__ . '/include/cli-utilities.php';
 62	
 63	// ============================================================================
 64	// Menu display
 65	// ============================================================================
 66	
 67	/**
 68	 * Renders the numbered developer menu to STDOUT.
 69	 *
 70	 * @return void
 71	 */
 72	function showMenu() : void
 73	{
 74	    writeln();
 75	    writeln(color('=== Application Framework — Developer Menu ===', 'bold'));
 76	    writeln();
 77	    writeln('  ' . color('1', 'cyan') . '  Setup local environment');
 78	    writeln('  ' . color('2', 'cyan') . '  Build');
 79	    writeln('  ' . color('3', 'cyan') . '  Run tests');
 80	    writeln('  ' . color('4', 'cyan') . '  Clear caches');
 81	    writeln('  ' . color('5', 'cyan') . '  Seed test database');
 82	    writeln('  ' . color('6', 'cyan') . '  PHPStan analysis');
 83	    writeln();
 84	    writeln('  ' . color('0', 'cyan') . '  Exit');
 85	    writeln();
 86	}
 87	
 88	// ============================================================================
 89	// Action dispatch
 90	// ============================================================================
 91	
 92	/**
 93	 * Dispatches the user's menu choice to the appropriate command.
 94	 *
 95	 * Returns false when the caller should exit, true to continue looping.
 96	 *
 97	 * @param string $choice The raw input string entered by the user.
 98	 * @return bool False to exit the menu loop, true to continue.
 99	 */
100	function dispatchChoice(string $choice) : bool

101	{
102	    switch ($choice)
103	    {
104	        case '1':
105	            writeln(color('--- Setup local environment ---', 'yellow'));
106	            passthru('php ' . escapeshellarg(__DIR__ . '/setup-local.php'));
107	            break;
108	
109	        case '2':
110	            writeln(color('--- Build ---', 'yellow'));
111	            passthru('composer build');
112	            break;
113	
114	        case '3':
115	            $filter = prompt('Filter pattern (empty = full suite)');
116	
117	            if ($filter !== '')
118	            {
119	                writeln(color('--- Tests (filter: ' . $filter . ') ---', 'yellow'));
120	                passthru('composer test-filter -- ' . escapeshellarg($filter));
121	            }
122	            else
123	            {
124	                writeln(color('--- Tests (full suite) ---', 'yellow'));
125	                passthru('composer test');
126	            }
127	            break;
128	
129	        case '4':
130	            writeln(color('--- Clear caches ---', 'yellow'));
131	            passthru('composer clear-caches');
132	            break;
133	
134	        case '5':
135	            writeln(color('--- Seed test database ---', 'yellow'));
136	            passthru('composer seed-tests');
137	            break;
138	
139	        case '6':
140	            writeln(color('--- PHPStan analysis ---', 'yellow'));
141	            passthru('composer analyze');
142	            break;
143	
144	        case '0':
145	            writeln(color('Goodbye!', 'green'));
146	            return false;
147	
148	        default:
149	            writeln(color('Unknown option: ' . $choice, 'red'));
150	            break;
151	    }
152	
153	    return true;
154	}
155	
156	// ============================================================================
157	// Main loop
158	// ============================================================================
159	
160	while (true)
161	{
162	    showMenu();
163	    $choice = prompt('Select option');
164	
165	    if (!dispatchChoice($choice))
166	    {
167	        break;
168	    }
169	}

